	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/tags/{id}", wrapper.DeleteTag)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/tags/{id}", wrapper.PatchTag)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/sync/changes", wrapper.GetChanges)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/push/vapid-public-key", wrapper.GetVapidPublicKey)
