// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {

	// (DELETE /checklist-items/{id})
	DeleteChecklistItem(ctx context.Context, request DeleteChecklistItemRequestObject) (DeleteChecklistItemResponseObject, error)

	// (PATCH /checklist-items/{id})
	PatchChecklistItem(ctx context.Context, request PatchChecklistItemRequestObject) (PatchChecklistItemResponseObject, error)
	// ListCompletions Completed occurrences across tasks, newest first
	// (GET /completions)
	ListCompletions(ctx context.Context, request ListCompletionsRequestObject) (ListCompletionsResponseObject, error)
	// ListLists All lists the caller is a member of
	// (GET /lists)
	ListLists(ctx context.Context, request ListListsRequestObject) (ListListsResponseObject, error)
	// CreateList Create a list (idempotent on `id`)
	// (POST /lists)
	CreateList(ctx context.Context, request CreateListRequestObject) (CreateListResponseObject, error)

	// (DELETE /lists/{id})
	DeleteList(ctx context.Context, request DeleteListRequestObject) (DeleteListResponseObject, error)

	// (GET /lists/{id})
	GetList(ctx context.Context, request GetListRequestObject) (GetListResponseObject, error)

	// (PATCH /lists/{id})
	PatchList(ctx context.Context, request PatchListRequestObject) (PatchListResponseObject, error)

	// (POST /lists/{id}/restore)
	RestoreList(ctx context.Context, request RestoreListRequestObject) (RestoreListResponseObject, error)
	// GetMe Current user profile
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// PatchMe Update profile settings
	// (PATCH /me)
	PatchMe(ctx context.Context, request PatchMeRequestObject) (PatchMeResponseObject, error)
	// ListPushSubscriptions Devices registered for notifications
	// (GET /push/subscriptions)
	ListPushSubscriptions(ctx context.Context, request ListPushSubscriptionsRequestObject) (ListPushSubscriptionsResponseObject, error)
	// CreatePushSubscription Register a device (idempotent on `id` and on `endpoint`)
	// (POST /push/subscriptions)
	CreatePushSubscription(ctx context.Context, request CreatePushSubscriptionRequestObject) (CreatePushSubscriptionResponseObject, error)

	// (DELETE /push/subscriptions/{id})
	DeletePushSubscription(ctx context.Context, request DeletePushSubscriptionRequestObject) (DeletePushSubscriptionResponseObject, error)
	// TestPushSubscription Send a test notification to this device
	// (POST /push/subscriptions/{id}/test)
	TestPushSubscription(ctx context.Context, request TestPushSubscriptionRequestObject) (TestPushSubscriptionResponseObject, error)
	// GetVapidPublicKey Public key the browser needs to subscribe to Web Push
	// (GET /push/vapid-public-key)
	GetVapidPublicKey(ctx context.Context, request GetVapidPublicKeyRequestObject) (GetVapidPublicKeyResponseObject, error)

	// (DELETE /reminders/{id})
	DeleteReminder(ctx context.Context, request DeleteReminderRequestObject) (DeleteReminderResponseObject, error)

	// (PATCH /reminders/{id})
	PatchReminder(ctx context.Context, request PatchReminderRequestObject) (PatchReminderResponseObject, error)
	// GetChanges Incremental changes since a cursor
	// (GET /sync/changes)
	GetChanges(ctx context.Context, request GetChangesRequestObject) (GetChangesResponseObject, error)

	// (GET /tags)
	ListTags(ctx context.Context, request ListTagsRequestObject) (ListTagsResponseObject, error)
	// CreateTag Create a tag (idempotent on `id`)
	// (POST /tags)
	CreateTag(ctx context.Context, request CreateTagRequestObject) (CreateTagResponseObject, error)

	// (DELETE /tags/{id})
	DeleteTag(ctx context.Context, request DeleteTagRequestObject) (DeleteTagResponseObject, error)

	// (PATCH /tags/{id})
	PatchTag(ctx context.Context, request PatchTagRequestObject) (PatchTagResponseObject, error)
	// ListTasks Query tasks
	// (GET /tasks)
	ListTasks(ctx context.Context, request ListTasksRequestObject) (ListTasksResponseObject, error)
	// CreateTask Create a task (idempotent on `id`)
	// (POST /tasks)
	CreateTask(ctx context.Context, request CreateTaskRequestObject) (CreateTaskResponseObject, error)

	// (DELETE /tasks/{id})
	DeleteTask(ctx context.Context, request DeleteTaskRequestObject) (DeleteTaskResponseObject, error)

	// (GET /tasks/{id})
	GetTask(ctx context.Context, request GetTaskRequestObject) (GetTaskResponseObject, error)

	// (PATCH /tasks/{id})
	PatchTask(ctx context.Context, request PatchTaskRequestObject) (PatchTaskResponseObject, error)
	// CreateChecklistItem Add a checklist item (idempotent on `id`)
	// (POST /tasks/{id}/checklist-items)
	CreateChecklistItem(ctx context.Context, request CreateChecklistItemRequestObject) (CreateChecklistItemResponseObject, error)
	// CompleteTask Complete a task or the current occurrence of a recurring task
	// (POST /tasks/{id}/complete)
	CompleteTask(ctx context.Context, request CompleteTaskRequestObject) (CompleteTaskResponseObject, error)
	// ListTaskCompletions Completion history, newest first
	// (GET /tasks/{id}/completions)
	ListTaskCompletions(ctx context.Context, request ListTaskCompletionsRequestObject) (ListTaskCompletionsResponseObject, error)
	// CreateReminder Add a reminder (idempotent on `id`)
	// (POST /tasks/{id}/reminders)
	CreateReminder(ctx context.Context, request CreateReminderRequestObject) (CreateReminderResponseObject, error)

	// (POST /tasks/{id}/restore)
	RestoreTask(ctx context.Context, request RestoreTaskRequestObject) (RestoreTaskResponseObject, error)
	// SkipTaskOccurrence Skip the current occurrence of a recurring task
	// (POST /tasks/{id}/skip)
	SkipTaskOccurrence(ctx context.Context, request SkipTaskOccurrenceRequestObject) (SkipTaskOccurrenceResponseObject, error)
	// SnoozeTask Create a one-off `snooze` reminder (idempotent on `reminder_id`)
	// (POST /tasks/{id}/snooze)
	SnoozeTask(ctx context.Context, request SnoozeTaskRequestObject) (SnoozeTaskResponseObject, error)
	// UncompleteTask Undo a completion or skip
	// (POST /tasks/{id}/uncomplete)
	UncompleteTask(ctx context.Context, request UncompleteTaskRequestObject) (UncompleteTaskResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

